/* From Uiverse.io by martinval9 - Tags: switch */
/* The switch - the box around the slider */
.__UIV_SCOPE__ .switch {
 font-size: 11px;
 position: relative;
 display: inline-block;
 width: 3.5em;
 height: 1em;
}

/* Hide default HTML checkbox */
.__UIV_SCOPE__ .switch input {
 opacity: 0;
 width: 0;
 height: 0;
}

/* The slider */
.__UIV_SCOPE__ .slider {
 position: absolute;
 cursor: pointer;
 top: 0;
 left: 0;
 right: 0;
 bottom: 0;
 background-color: #ccc;
 border: 2px solid #000;
 transition: .4s;
 border-radius: 1px;
}

.__UIV_SCOPE__ .slider:before {
 position: absolute;
 content: "";
 height: 1.3em;
 width: 1.2em;
 border-radius: 2px;
 left: 0.2em;
 bottom: 0.3em;
 background-color: #fff;
 border: 2px solid #000;
 transition: 0.1s;
}

.__UIV_SCOPE__ input:checked + .slider {
 background-color: #000;
}

.__UIV_SCOPE__ input:focus + .slider {
 box-shadow: 0 0 1px #2196F3;
}

.__UIV_SCOPE__ input:checked + .slider:before {
 transform: translateX(1.3em);
}
